lines.query:
SELECT (MIN(?name) AS ?thing) (IF(SAMPLE(?higher), SAMPLE(?best), -SAMPLE(?best)) AS ?score) (MIN(?pname) AS ?paper) WHERE {
  {
    SELECT ?t (MAX(?bkey) AS ?best) WHERE {
      ?bv a ev:Value ; ev:of ?t ; ev:onMetric ?bm ; ev:number ?bnumber ; ev:inExperiment ?be ; kg:contextKey "ICSI Meeting Recorder Dialog Act Corpus (MRDA)" .
      ?bm ev:name ?metric .
      ?be ev:inPaper ?bp .
      ?bp ev:name ?bpaper .
      OPTIONAL { ?bm kg:higherIsBetter ?bh }
      BIND(IF(COALESCE(?bh, true), ?bnumber, -?bnumber) AS ?bkey)
      $include[?bpaper]
    }
    GROUP BY ?t
  }
  ?v a ev:Value ; ev:of ?t ; ev:onMetric ?m ; ev:number ?number ; ev:inExperiment ?e ; kg:contextKey "ICSI Meeting Recorder Dialog Act Corpus (MRDA)" .
  ?m ev:name ?metric .
  ?t ev:name ?name .
  ?e ev:inPaper ?p .
  ?p ev:name ?pname .
  OPTIONAL { ?m kg:higherIsBetter ?h }
  BIND(COALESCE(?h, true) AS ?higher)
  BIND(IF(?higher, ?number, -?number) AS ?key)
  FILTER(?key = ?best)
  $include[?pname]
}
GROUP BY ?t
ORDER BY DESC(SAMPLE(?best)) ?thing
